#include <iostream>
using namespace std;

/** @pre n >= 0
    @post Retorna el numero de parejas de digitos consecutivos distintos de n. */
int canvis(int n) {
    int res = 0;
    int ant = n % 10;
    n = n / 10;
    while (n > 0) {
        int d = n % 10;
        if (d != ant) ++res;
        ant = d;
        n = n / 10;
    }
    return res;
}

int main() {
    int t;
    cin >> t;
    for (int i = 0; i < t; ++i) {
        int n;
        cin >> n;
        cout << canvis(n) << endl;
    }
}

Casos límite: n de un dígito (incluido 0) da 0. Se compara cada dígito con el anterior extraído, de derecha a izquierda (el número de cambios es el mismo).

#include <iostream>
using namespace std;

int main() {
    char c;
    cin >> c;
    char ant = ' ';
    int racha = 0;
    int maxim = 0;
    while (c != '.') {
        if (c == ant) ++racha;
        else racha = 1;
        if (racha > maxim) maxim = racha;
        ant = c;
        cin >> c;
    }
    cout << maxim << endl;
}

La primera lectura es segura porque la secuencia siempre acaba en '.'. 'ant' inicial ' ' nunca coincide con una letra.

#include <iostream>
using namespace std;

int main() {
    char c;
    cin >> c;
    int valor = 0;
    int peso = 1;
    while (c != '.') {
        if (c == '*') {
            cout << char(valor);
            valor = 0;
            peso = 1;
        } else {
            valor += (c - '0') * peso;
            peso *= 2;
        }
        cin >> c;
    }
    cout << endl;
}

