#include <iostream>
#include <cstdlib>
using namespace std;

/** @pre x >= 0, y >= 0
    @post Retorna la suma de |dx - dy| sobre las posiciones de digitos,
          alineando por la derecha y con digito 0 donde falte. */
int dif(int x, int y) {
    if (x == 0 and y == 0) return 0;
    return abs(x % 10 - y % 10) + dif(x / 10, y / 10);
}

int main() {
    int t;
    cin >> t;
    for (int i = 0; i < t; ++i) {
        int x, y;
        cin >> x >> y;
        cout << dif(x, y) << endl;
    }
}

Caso base x == 0 and y == 0 (también cubre la pareja 0 0, que da 0); el paso trata el último dígito y recurre con x/10, y/10.

