#include <iostream>

/*
   @pre:Entrada: 3 1123 7 90909
   @pos: alida: 2, 0, 4
*/

int	canvis(int n)
{
	int	c;
	int	cnt;

	cnt = 2000000000;

	c = 0;
	while (0 <= n &&  n <= cnt)
		c++;
	return (c);
}

int	main(void)
{
	int	nbr;

	while (std::cin >> nbr)
		std::cout << canvis(nbr) << '\n';
	return (0);
}
